import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice returns a draft invoice with line details from the catalogue', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2025-10-15');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 1);
  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[0].name, 'Design work (hour)');
  assert.equal(invoice.lines[0].qty, 5);
  assert.equal(invoice.lines[0].unitPrice, 8500);
  assert.equal(invoice.lines[0].vatRate, 21);
});

test('createInvoice handles multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-12-25',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.lines.length, 3);
  assert.equal(invoice.lines[0].name, 'Design work (hour)');
  assert.equal(invoice.lines[1].name, 'Development (hour)');
  assert.equal(invoice.lines[2].name, 'Sticker sheet');
});

test('createInvoice rejects an unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects an invalid date format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025/10/15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects a non-existent date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects a missing date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects an empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects a non-array lines parameter', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: null,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects a zero quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects a negative quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects a fractional quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects an unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'NOPE-SKU', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const linesCopy = JSON.stringify(lines);
  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines,
  });
  assert.equal(JSON.stringify(lines), linesCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 5,
    unitPrice: 8500,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal works with qty of 1', () => {
  const line = {
    sku: 'STICKER',
    name: 'Sticker sheet',
    qty: 1,
    unitPrice: 50,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 50);
});

test('lineTotal works with large quantities', () => {
  const line = {
    sku: 'ICON-SET',
    name: 'Icon set (24 icons)',
    qty: 1000,
    unitPrice: 980,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 980000);
});

test('invoiceTotals returns subtotal and total for a single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 5,
        unitPrice: 8500,
        vatRate: 21,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 2,
        unitPrice: 8500,
        vatRate: 21,
      },
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
      },
      {
        sku: 'STICKER',
        name: 'Sticker sheet',
        qty: 100,
        unitPrice: 50,
        vatRate: 21,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000 + 95000 + 5000);
  assert.equal(totals.total, 117000);
});

test('invoiceTotals works with an empty invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'draft',
    lines: [],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  const updated = r.value;
  assert.equal(updated.lines.length, 2);
  assert.equal(updated.lines[1].sku, 'DEV-HOUR');
  assert.equal(updated.lines[1].qty, 3);
});

test('addLine increments qty if the SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  const updated = r.value;
  assert.equal(updated.lines.length, 1);
  assert.equal(updated.lines[0].qty, 5);
});

test('addLine increments existing line in a multi-line invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 100 },
    ],
  }).value;

  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(r.ok, true);
  const updated = r.value;
  assert.equal(updated.lines.length, 3);
  assert.equal(updated.lines[1].qty, 15);
});

test('addLine rejects a zero quantity', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
