});

test('addLine rejects a negative quantity', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: -5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

