  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 2.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine rejects an unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'NOPE-SKU', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine refuses to modify a non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'sent',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 2,
        unitPrice: 8500,
